Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
[TestClass]
public sealed class EnvironmentSpecificTests
{
    private readonly TestContext _testContext;
    private string? _tempFilePath;

    public EnvironmentSpecificTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only: skip automatically on Linux/macOS
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(
            @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\.NETFramework",
            "InstallRoot", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI: runs only on developer machines
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    [Timeout(30000)]
    public async Task GpuRender_ProducesValidOutput()
    {
        var result = await GpuRenderer.RenderAsync(
            _testContext.CancellationToken);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API: retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync(
            "Seattle", _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
        Assert.IsNotEmpty(forecast.Days);
    }

    // 4. Temp file cleanup: [TestCleanup] runs even on failure
    [TestMethod]
    public void Export_WritesValidFile()
    {
        _tempFilePath = Path.Combine(
            Path.GetTempPath(), $"{Guid.NewGuid()}.csv");

        Exporter.WriteCsv(_tempFilePath, new[] { "a", "b" });

        Assert.IsTrue(File.Exists(_tempFilePath));
        var content = File.ReadAllText(_tempFilePath);
        Assert.Contains("a", content);
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFilePath is not null && File.Exists(_tempFilePath))
        {
            File.Delete(_tempFilePath);
        }
    }
}
```

**Key points:**

| Scenario | Solution | MSTest version |
|---|---|---|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` | 3.10+ |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | 3.10+ |
| Flaky API | `[Retry(3)]` — only for genuine external flakiness | 3.9+ |
| Cleanup on failure | `[TestCleanup]` — always runs, even if the test throws | All versions |

- `[OSCondition]` and `[CICondition]` **skip** the test (not fail) when the condition isn't met.
- `[Retry]` should not be used to mask bugs — only for external dependencies you can't control.
- Always pair `[Timeout]` with `TestContext.CancellationToken` for cooperative cancellation in async tests.
